package codicefiscale

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"io"
	"sort"
	"strings"
	"sync"
	"unicode/utf8"

	"golang.org/x/text/unicode/norm"
)

// unidecode.bin.gz is generated by tools/go-migration/codicefiscale_data.py:
// text_unidecode's replacements of code points 1..65535, NUL separated.
//
//go:embed unidecode.bin.gz
var unidecodeGzip []byte

// unidecodeTableLen is len(text_unidecode._replaces): code points above it are dropped.
const unidecodeTableLen = 65535

var (
	unidecodeOnce  sync.Once
	unidecodeTable []string
)

// unidecode returns text_unidecode's replacement of the code point r.
func unidecode(r rune) string {
	switch {
	case r == 0:
		return "\x00"
	case r > unidecodeTableLen:
		return "" // IndexError in text_unidecode: dropped
	}
	unidecodeOnce.Do(func() {
		reader, err := gzip.NewReader(bytes.NewReader(unidecodeGzip))
		if err != nil {
			panic(err)
		}
		raw, err := io.ReadAll(reader)
		if err != nil {
			panic(err)
		}
		unidecodeTable = strings.Split(string(raw), "\x00")
		if len(unidecodeTable) != unidecodeTableLen {
			panic("codicefiscale: unidecode table length")
		}
	})
	return unidecodeTable[r-1]
}

// pyRunes are the code points of a Python str. A lone surrogate reaches Go
// as its three-byte generalized UTF-8 form; any other malformed sequence has
// no Python counterpart (ok false).
func pyRunes(text string) (runes []rune, ok bool) {
	runes = make([]rune, 0, len(text))
	for i := 0; i < len(text); {
		r, size := utf8.DecodeRuneInString(text[i:])
		if r == utf8.RuneError && size == 1 {
			if i+2 < len(text) && text[i] == 0xed && text[i+1] >= 0xa0 && text[i+1] <= 0xbf && text[i+2] >= 0x80 && text[i+2] <= 0xbf {
				runes = append(runes, rune(text[i]&0x0f)<<12|rune(text[i+1]&0x3f)<<6|rune(text[i+2]&0x3f))
				i += 3
				continue
			}
			return nil, false
		}
		runes = append(runes, r)
		i += size
	}
	return runes, true
}

func isSurrogate(r rune) bool { return r >= 0xd800 && r <= 0xdfff }

// nfkd is unicodedata.normalize('NFKD', text) over code points: the full
// compatibility decomposition of each one, then the canonical ordering of
// every run of combining marks. (norm.NFKD over the whole string would break
// runs of more than 30 marks, which Python does not.)
func nfkd(text []rune) []rune {
	out := make([]rune, 0, len(text))
	classes := make([]uint8, 0, len(text))
	for _, r := range text {
		if r < 0x80 || isSurrogate(r) {
			out, classes = append(out, r), append(classes, 0)
			continue
		}
		for _, d := range norm.NFKD.String(string(r)) {
			out, classes = append(out, d), append(classes, norm.NFKD.PropertiesString(string(d)).CCC())
		}
	}
	for start := 0; start < len(out); {
		if classes[start] == 0 {
			start++
			continue
		}
		end := start
		for end < len(out) && classes[end] != 0 {
			end++
		}
		run := make([]int, end-start)
		for i := range run {
			run[i] = start + i
		}
		sort.SliceStable(run, func(a, b int) bool { return classes[run[a]] < classes[run[b]] })
		ordered := make([]rune, len(run))
		for i, index := range run {
			ordered[i] = out[index]
		}
		copy(out[start:end], ordered)
		start = end
	}
	return out
}

// slugify ports python-slugify 8.0.4 slugify(text) with default options.
// It returns ErrUnsupported for text that is no Python str.
func slugify(text string) (string, error) {
	runes, ok := pyRunes(text)
	if !ok {
		return "", ErrUnsupported
	}
	runes = replaceQuotes(runes, '-')
	var ascii strings.Builder
	for _, r := range nfkd(runes) {
		ascii.WriteString(unidecode(r))
	}
	// Character references are replaced in the transliterated (ASCII) text;
	// what they produce is decomposed again and every non-ASCII code point
	// then counts as a separator.
	runes = nfkd(htmlReferences([]rune(ascii.String())))
	for i, r := range runes {
		if r >= 'A' && r <= 'Z' {
			runes[i] = r + 'a' - 'A'
		}
	}
	runes = replaceQuotes(runes, -1)
	runes = removeDigitCommas(runes)

	var b strings.Builder
	dash := true // trims leading dashes and collapses runs
	for _, r := range runes {
		if r < 0x80 && isASCIIAlnum(byte(r)) {
			b.WriteByte(byte(r))
			dash = false
		} else if !dash {
			b.WriteByte('-')
			dash = true
		}
	}
	return strings.TrimRight(b.String(), "-"), nil
}

// replaceQuotes is QUOTE_PATTERN.sub(repl, text): every run of ' becomes repl
// (nothing when repl is negative).
func replaceQuotes(text []rune, repl rune) []rune {
	out := text[:0:0]
	inRun := false
	for _, r := range text {
		if r == '\'' {
			if !inRun && repl >= 0 {
				out = append(out, repl)
			}
			inRun = true
			continue
		}
		inRun = false
		out = append(out, r)
	}
	return out
}

// removeDigitCommas is NUMBERS_PATTERN.sub("", text). Only a comma between two
// ASCII digits matters: next to any other decimal digit the comma and that
// digit both end up as one separator.
func removeDigitCommas(text []rune) []rune {
	out := text[:0:0]
	digit := func(r rune) bool { return r >= '0' && r <= '9' }
	for i, r := range text {
		if r == ',' && i > 0 && i+1 < len(text) && digit(text[i-1]) && digit(text[i+1]) {
			continue
		}
		out = append(out, r)
	}
	return out
}

// decimalDigit is the value of a decimal digit (category Nd), as int() and
// the regex class \d read it.
func decimalDigit(r rune) (int, bool) {
	for _, zero := range decimalZeros {
		if r >= zero && r <= zero+9 {
			return int(r - zero), true
		}
	}
	return 0, false
}

// htmlReferences applies slugify's three substitutions in order: named
// entities, decimal references, hexadecimal references. A decimal or
// hexadecimal pass in which any reference is out of chr()'s range (or has
// more digits than int() converts) is dropped as a whole, as the exception
// Python swallows leaves the text unchanged.
func htmlReferences(text []rune) []rune {
	text = substituteReferences(text, "", func(body []rune) (rune, bool, bool) {
		for _, r := range body {
			if r >= 0x80 || !isASCIIAlnum(byte(r)) {
				return 0, false, true
			}
		}
		code, known := htmlEntities[string(body)]
		return code, known, true
	})
	text = substituteReferences(text, "#", func(body []rune) (rune, bool, bool) {
		return referenceNumber(body, 10)
	})
	return substituteReferences(text, "#x", func(body []rune) (rune, bool, bool) {
		return referenceNumber(body, 16)
	})
}

// pyIntMaxDigits is sys.get_int_max_str_digits(): int() of a longer decimal
// string raises ValueError (other bases are not limited).
const pyIntMaxDigits = 4300

// referenceNumber reads the digits of a numeric reference. matched is false
// when the body is not all digits of the base; valid is false when chr()
// (or int()) raises for it.
func referenceNumber(body []rune, base int) (code rune, matched, valid bool) {
	if len(body) == 0 {
		return 0, false, true
	}
	value, overflow := int64(0), false
	for _, r := range body {
		digit, ok := decimalDigit(r)
		if !ok && base == 16 {
			switch {
			case r >= 'a' && r <= 'f':
				digit, ok = int(r-'a')+10, true
			case r >= 'A' && r <= 'F':
				digit, ok = int(r-'A')+10, true
			}
		}
		if !ok {
			return 0, false, true
		}
		if value = value*int64(base) + int64(digit); value > 0x10ffff {
			overflow = true
			value = 0x110000
		}
	}
	if overflow || base == 10 && len(body) > pyIntMaxDigits {
		return 0, true, false
	}
	return rune(value), true, true
}

// substituteReferences replaces every `&<prefix><body>;` whose body the
// resolver matches, scanning left to right without overlap like re.sub. The
// body is the shortest run up to the next ';' (no pattern body holds one).
func substituteReferences(text []rune, prefix string, resolve func(body []rune) (code rune, matched, valid bool)) []rune {
	lead := []rune("&" + prefix)
	out := make([]rune, 0, len(text))
	for i := 0; i < len(text); {
		if !hasRunePrefix(text[i:], lead) {
			out = append(out, text[i])
			i++
			continue
		}
		end := -1
		for j := i + len(lead); j < len(text); j++ {
			if text[j] == ';' {
				end = j
				break
			}
		}
		if end < 0 {
			out = append(out, text[i])
			i++
			continue
		}
		code, matched, valid := resolve(text[i+len(lead) : end])
		switch {
		case !matched:
			out = append(out, text[i])
			i++
		case !valid:
			return text
		default:
			out = append(out, code)
			i = end + 1
		}
	}
	return out
}

func hasRunePrefix(text, prefix []rune) bool {
	if len(text) < len(prefix) {
		return false
	}
	for i, r := range prefix {
		if text[i] != r {
			return false
		}
	}
	return true
}

func isASCIIDigit(c byte) bool { return '0' <= c && c <= '9' }

func isASCIIAlnum(c byte) bool {
	return isASCIIDigit(c) || ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
}
